-- 0178: Kaiju No. 8 — Hoshinas Duell mit Kafka folgte auf Kaiju Nr. 9s Angriff auf den
-- Stützpunkt Tachikawa (nicht Sagamihara); die Frage nach dem Stützpunkt nach der Festnahme
-- („Ariake“) war nicht belegbar und fragt jetzt, wer Kafka im Duell prüft (Isao Shinomiya).
-- Idempotent: nur solange die alten deutschen Texte stehen.
update question_translations set explanation = 'Kafka stops the blade and snaps it in two – Hoshina had already cut off one of his hands.', prompt = 'What does Kafka break when Hoshina confronts him after Kaiju No. 9’s attack on Tachikawa Base?' where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka detiene la hoja y la parte en dos; antes, Hoshina le había cortado una mano.', prompt = '¿Qué rompe Kafka cuando Hoshina se enfrenta a él tras el ataque del Kaiju n.º 9 a la base de Tachikawa?' where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka bloque la lame et la brise en deux – Hoshina lui avait déjà tranché une main.', prompt = 'Que brise Kafka quand Hoshina l’affronte après l’attaque du Kaiju n° 9 contre la base de Tachikawa ?' where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka segura a lâmina e a parte ao meio – Hoshina já tinha decepado uma das mãos dele.', prompt = 'O que Kafka quebra quando Hoshina o enfrenta depois do ataque do Kaiju nº 9 à base de Tachikawa?' where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka blocca la lama e la spezza in due: Hoshina gli aveva già tagliato una mano.', prompt = 'Che cosa spezza Kafka quando Hoshina lo affronta dopo l’attacco del Kaiju N. 9 alla base di Tachikawa?' where lang = 'it' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka menahan bilahnya lalu mematahkannya – sebelumnya Hoshina sudah memotong salah satu tangannya.', prompt = 'Apa yang dipatahkan Kafka saat Hoshina menghadangnya setelah serangan Kaiju No. 9 ke Markas Tachikawa?' where lang = 'id' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka kılıcı durdurup ikiye böler; Hoshina daha önce ellerinden birini kesmişti.', prompt = 'Kaiju No. 9’un Tachikawa Üssü’ne saldırısından sonra Hoshina onunla yüzleştiğinde Kafka neyi kırar?' where lang = 'tr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka zatrzymuje ostrze i łamie je na pół – wcześniej Hoshina odciął mu dłoń.', prompt = 'Co łamie Kafka, gdy Hoshina staje z nim do walki po ataku Kaiju nr 9 na bazę Tachikawa?' where lang = 'pl' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Kafka chặn lưỡi kiếm rồi bẻ đôi nó – trước đó Hoshina đã chém đứt một bàn tay của anh.', prompt = 'Kafka bẻ gãy thứ gì khi Hoshina đối đầu với anh sau cuộc tấn công của Kaiju số 9 vào căn cứ Tachikawa?' where lang = 'vi' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'カフカは刃を受け止めてへし折りました。その前に保科はカフカの片手を斬り落としていました。', prompt = '怪獣9号の立川基地襲撃の後、保科と対決したカフカが折ったものは？' where lang = 'ja' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = '카프카는 칼날을 막아 두 동강 냈어요. 그 전에 호시나는 카프카의 한 손을 베어 냈죠.', prompt = '괴수 9호의 다치카와 기지 습격 후 호시나와 맞붙은 카프카가 부러뜨린 것은?' where lang = 'ko' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'คาฟกะรับคมดาบไว้แล้วหักเป็นสองท่อน ก่อนหน้านั้นโฮชินะฟันมือเขาขาดไปข้างหนึ่ง', prompt = 'หลังไคจูหมายเลข 9 บุกฐานทาจิคาวะ คาฟกะหักอะไรตอนที่โฮชินะเข้าปะทะ?' where lang = 'th' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Кафка останавливает клинок и ломает его пополам – до этого Хосина отрубил ему руку.', prompt = 'Что ломает Кафка, когда Хосина вступает с ним в бой после нападения Кайдзю № 9 на базу Тачикава?' where lang = 'ru' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'يوقف كافكا النصل ويكسره نصفين، وكان هوشينا قد قطع إحدى يديه قبل ذلك.', prompt = 'ماذا يكسر كافكا حين يواجهه هوشينا بعد هجوم الكايجو رقم 9 على قاعدة تاتشيكاوا؟' where lang = 'ar' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'The Director General fights him personally – Kafka passes and is then assigned to the First Division.', prompt = 'Who tests Kafka at headquarters after his capture as Kaiju No. 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'en' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'El director general lucha contra él en persona; Kafka supera la prueba y pasa a la Primera División.', prompt = '¿Quién pone a prueba a Kafka en el cuartel general tras su captura como Kaiju n.º 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'es' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Le directeur général l’affronte en personne – Kafka réussit et rejoint ensuite la 1re division.', prompt = 'Qui met Kafka à l’épreuve au quartier général après sa capture en tant que Kaiju n° 8 ?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'fr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'O diretor-geral luta contra ele pessoalmente – Kafka passa no teste e vai para a 1ª Divisão.', prompt = 'Quem testa Kafka no quartel-general depois de sua captura como Kaiju nº 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'pt' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Il Direttore Generale lo affronta di persona: Kafka supera la prova e passa alla Prima Divisione.', prompt = 'Chi mette alla prova Kafka al quartier generale dopo la sua cattura come Kaiju N. 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'it' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Direktur Jenderal sendiri melawannya – Kafka lulus dan lalu masuk Divisi 1.', prompt = 'Siapa yang menguji Kafka di markas besar setelah ia ditangkap sebagai Kaiju No. 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'id' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Genel Direktör onunla bizzat dövüşür; Kafka sınavı geçer ve ardından 1. Tümen’e atanır.', prompt = 'Kaiju No. 8 olarak yakalandıktan sonra Kafka’yı karargâhta kim sınar?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'tr' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Dyrektor generalny walczy z nim osobiście – Kafka zdaje próbę i trafia do 1. Dywizji.', prompt = 'Kto sprawdza Kafkę w kwaterze głównej po jego schwytaniu jako Kaiju nr 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'pl' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Tổng tư lệnh đích thân đấu với anh – Kafka vượt qua và được chuyển đến Sư đoàn 1.', prompt = 'Ai thử thách Kafka tại tổng hành dinh sau khi anh bị bắt với danh tính Kaiju số 8?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'vi' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = '長官自らが戦い、カフカは認められて第1部隊へ配属されました。', prompt = '怪獣8号として拘束されたカフカを本部で試したのは誰？', options = '["四ノ宮功", "鳴海弦", "保科宗四郎", "亜白ミナ"]'::jsonb where lang = 'ja' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = '장관이 직접 싸웠고, 카프카는 인정받아 제1부대로 배속돼요.', prompt = '괴수 8호로 붙잡힌 카프카를 본부에서 시험한 사람은?', options = '["시노미야 이사오", "나루미 겐", "호시나 소시로", "아시로 미나"]'::jsonb where lang = 'ko' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'ผู้บัญชาการสูงสุดลงมือสู้เอง คาฟกะผ่านการทดสอบและถูกย้ายไปกองพลที่ 1', prompt = 'ใครทดสอบคาฟกะที่กองบัญชาการ หลังเขาถูกจับในฐานะไคจูหมายเลข 8?', options = '["ชิโนมิยะ อิซาโอะ", "นารุมิ เก็น", "โฮชินะ โซชิโร่", "อาชิโระ มินะ"]'::jsonb where lang = 'th' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Генеральный директор лично сражается с ним – Кафка проходит испытание и попадает в 1-ю дивизию.', prompt = 'Кто испытывает Кафку в штабе после его поимки как Кайдзю № 8?', options = '["Исао Синомия", "Гэн Наруми", "Сосиро Хосина", "Мина Асиро"]'::jsonb where lang = 'ru' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'يقاتله المدير العام بنفسه، فينجح كافكا ويُنقل بعدها إلى الفرقة الأولى.', prompt = 'من يختبر كافكا في المقر الرئيسي بعد القبض عليه بوصفه الكايجو رقم 8؟', options = '["إيساو شينوميا", "غين نارومي", "سوشيرو هوشينا", "مينا أشيرو"]'::jsonb where lang = 'ar' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
update question_translations set explanation = 'Kafka hält die Klinge auf und bricht sie entzwei – zuvor hatte Hoshina ihm eine Hand abgetrennt.', prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 auf den Stützpunkt Tachikawa zum Kampf stellt?' where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Was zerbricht Kafka, als Hoshina ihn nach dem Angriff von Kaiju Nr. 9 in Sagamihara zum Kampf stellt?');
update question_translations set explanation = 'Der Generaldirektor kämpft selbst gegen ihn – Kafka besteht und kommt danach in die 1. Division.', prompt = 'Wer stellt Kafka nach seiner Festnahme als Kaiju Nr. 8 im Hauptquartier auf die Probe?', options = '["Isao Shinomiya", "Gen Narumi", "Soshiro Hoshina", "Mina Ashiro"]'::jsonb where lang = 'de' and question_id = (select question_id from question_translations where lang = 'de' and prompt = 'Zu welchem Stützpunkt wird Kafka nach seiner Festnahme als Kaiju Nr. 8 gebracht?');
